// Validate and normalize incoming deal payload
const body = $input.first().json.body || $input.first().json;

if (!body.name) {
  throw new Error('Missing required field: name');
}

return [{
  json: {
    company_name: body.company_name || body.name + ' Corp',
    company_sector: body.sector || 'Technology',
    company_country: body.country || 'US',
    contact_first: body.contact_first || 'Primary',
    contact_last: body.contact_last || 'Contact',
    contact_email: body.contact_email || null,
    contact_phone: body.contact_phone || null,
    deal_name: body.name,
    deal_type: body.deal_type || 'M&A',
    sector: body.sector || 'Technology',
    deal_size_usd: Number(body.deal_size_usd) || 50000000,
    description: body.description || 'Imported via n8n ingestion workflow',
    raw_payload: body
  }
}];

